const API='/api/ultron';
const $=s=>document.querySelector(s);
let items=[],mode='adaptive',speakEnabled=true,recognition=null,voiceLoop=false,lastReplyText='',settings={ai_enabled:false,memory_enabled:true,daily_brief_enabled:true,daily_ai_brief:false,daily_brief_hour:8},conversationId=localStorage.getItem('ultron_conversation_id')||crypto.randomUUID();
localStorage.setItem('ultron_conversation_id',conversationId);
const lessons=[
['The 2-minute rule','If a task takes less than two minutes, do it now. Small actions stop becoming mental clutter. Try it: clear one tiny task from your list.'],
['Break the task down','A vague goal creates friction. Turn “work on my business” into one visible next action you can finish in 15 minutes.'],
['Active recall','After learning something, close the notes and explain it from memory. Retrieval strengthens learning more than rereading alone.'],
['Time blocking','Give important work a place in your calendar. Protect one 25-minute block for the task that matters most.'],
['The 80/20 lens','Look for the small number of actions creating most of your progress. Do more of those before adding new commitments.'],
['If–then planning','Turn intention into a trigger: “If I finish breakfast, then I spend 10 minutes learning.” Specific cues make habits easier to start.']
];
let lessonIndex=0;
function toast(t){const e=$('#toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2600)}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function time(){const d=new Date(),zone=Intl.DateTimeFormat().resolvedOptions().timeZone||'Device local time';$('#today').textContent=d.toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'});$('#clock').textContent=d.toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit',hour12:true});const h=d.getHours();$('#greeting').textContent=(h<5?'Good night':h<12?'Good morning':h<17?'Good afternoon':h<21?'Good evening':'Good night')+'.';const z=$('#timeZoneLabel');if(z)z.textContent='PHONE TIME · '+zone+' · '+d.toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit',timeZoneName:'short'});}
async function req(path,method='GET',body){const r=await fetch(API+path,{method,headers:{'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});let data={};try{data=await r.json()}catch{}if(!r.ok){const e=new Error(data.error||'Request failed.');e.status=r.status;e.code=data.code;throw e}return data}
async function loadItems(){try{items=(await req('/items')).items||[];renderItems()}catch(e){$('#taskList').innerHTML='<div class="empty">Your private workspace could not load. Sign in to Hatchable and refresh.</div>';toast(e.message)}}
function renderItems(){const tasks=items.filter(x=>['task','reminder'].includes(x.kind));const goals=items.filter(x=>x.kind==='goal'&&x.status==='open');$('#openCount').textContent=tasks.filter(x=>x.status==='open').length;$('#doneCount').textContent=items.filter(x=>x.status==='done').length;$('#goalCount').textContent=goals.length;const visible=tasks.filter(x=>x.status!=='archived');$('#taskList').innerHTML=visible.length?visible.map(x=>'<div class="item '+(x.status==='done'?'done':'')+'"><button class="check" data-action="toggle" data-id="'+esc(x.id)+'" aria-label="Toggle task">'+(x.status==='done'?'✓':'')+'</button><div class="itemcopy"><strong>'+esc(x.title)+'</strong><small>'+esc(x.kind.toUpperCase())+' · '+(x.status==='done'?'COMPLETED':'OPEN')+'</small></div><button class="delete" data-action="delete" data-id="'+esc(x.id)+'" aria-label="Archive">×</button></div>').join(''):'<div class="empty">Nothing on your list yet. Add one small next step above.</div>'}
$('#taskForm').addEventListener('submit',async e=>{e.preventDefault();const title=$('#taskTitle').value.trim();if(!title)return;try{await req('/items','POST',{kind:$('#taskKind').value,title});$('#taskTitle').value='';await loadItems();toast('Added to your day.')}catch(err){toast(err.message)}});
$('#taskList').addEventListener('click',async e=>{const b=e.target.closest('button[data-action]');if(!b)return;const x=items.find(i=>i.id===b.dataset.id);if(!x)return;try{if(b.dataset.action==='toggle')await req('/items','PUT',{id:x.id,status:x.status==='done'?'open':'done'});else await req('/items','DELETE',{id:x.id});await loadItems()}catch(err){toast(err.message)}});
function bubble(text,who){const d=document.createElement('div');d.className='bubble '+who;d.textContent=text;$('#chat').append(d);$('#chat').scrollTop=$('#chat').scrollHeight;return d}
function localReply(q){const s=q.toLowerCase();let m=mode;if(mode==='adaptive')m=/learn|teach|explain|study|understand/.test(s)?'teacher':/feel|lonely|sad|stress|talk|relationship/.test(s)?'companion':/health|pain|symptom|medicine|doctor/.test(s)?'wellness':'strategist';if(m==='teacher')return 'Let’s learn this step by step. Tell me the topic and your current level. I’ll break it into small lessons, show an example and give you a short exercise.';if(m==='companion')return 'I’m here with you. Tell me what happened or what’s on your mind. We can take it one piece at a time. I’m an AI companion, but I can listen and support you.';if(m==='wellness')return 'I can help explain general health information and prepare questions for a licensed clinician. I can’t diagnose or prescribe. If this may be an emergency, contact emergency services.';if(/plan my day|today|priorit|organize/.test(s)){const open=items.filter(x=>['task','reminder'].includes(x.kind)&&x.status==='open');return open.length?'You have '+open.length+' open task(s): '+open.slice(0,5).map(x=>x.title).join('; ')+'. Start with the most consequential, then one quick task.':'Your list is clear. Choose one important outcome, one maintenance task and one thing for yourself.'}return 'I can help plan, teach, research and organize. The full AI brain is currently off. Enable it in ULTRON controls when you are ready.'}
let voiceBusy=false,voiceRestartTimer=null,wakeWordMode=false;
let speechVoices=[];
function refreshSpeechVoices(){if(!('speechSynthesis'in window))return;speechVoices=window.speechSynthesis.getVoices()||[];const select=$('#voiceChoice');if(!select)return;const prior=localStorage.getItem('ultron_voice_uri')||'auto';select.innerHTML='<option value="auto">Natural device voice · automatic</option>'+speechVoices.filter(v=>/^en(-|_)/i.test(v.lang)).map(v=>'<option value="'+esc(v.voiceURI)+'">'+esc(v.name)+' · '+esc(v.lang)+(v.localService?' · device':'')+'</option>').join('');select.value=speechVoices.some(v=>v.voiceURI===prior)?prior:'auto';}
if('speechSynthesis'in window){refreshSpeechVoices();window.speechSynthesis.onvoiceschanged=refreshSpeechVoices;}
$('#voiceChoice')?.addEventListener('change',e=>{localStorage.setItem('ultron_voice_uri',e.target.value);toast(e.target.value==='auto'?'Automatic natural voice selected.':'Speaking voice updated.')});
$('#voicePreview')?.addEventListener('click',()=>speak('Hello. I am ULTRON. I am here, and I am listening. What would you like us to work on?'));
function speak(t,onend){if(!('speechSynthesis'in window)){if(onend)onend();return}window.speechSynthesis.cancel();const spoken=String(t||'').replace(/https?:\/\/\S+/g,'').replace(/[*_#>]/g,'').replace(/\s+/g,' ').trim();const u=new SpeechSynthesisUtterance(spoken);const voices=speechVoices.length?speechVoices:window.speechSynthesis.getVoices();const saved=localStorage.getItem('ultron_voice_uri')||'auto';let chosen=voices.find(v=>v.voiceURI===saved);if(!chosen){const english=voices.filter(v=>/^en(-|_)/i.test(v.lang));const locale=navigator.language||'en-KE';chosen=english.sort((a,b)=>{const score=v=>(v.lang.toLowerCase()===locale.toLowerCase()?5:v.lang.toLowerCase().startsWith('en-ke')?4:v.lang.toLowerCase().startsWith('en-gb')?3:v.lang.toLowerCase().startsWith('en-us')?2:1)+(/natural|neural|premium|enhanced|samantha|ava|zoe|karen|daniel|aria|jenny/i.test(v.name)?2:0)+(v.localService?0.2:0);return score(b)-score(a)})[0]}u.voice=chosen||null;u.lang=chosen?.lang||navigator.language||'en-KE';u.rate=1.02;u.pitch=1.04;u.volume=1;u.onend=()=>{if(onend)onend()};u.onerror=()=>{if(onend)onend()};window.speechSynthesis.speak(u)}
async function runResearch(query){
 const q=String(query||'').trim();if(!q)throw new Error('Tell me what you want researched.');
 $('#researchQuery').value=q;$('#researchMeta').textContent='Searching free public sources…';$('#researchResults').innerHTML='<div class="empty">Researching…</div>';
 const r=await req('/research?q='+encodeURIComponent(q));
 const xs=r.results||[];$('#researchMeta').textContent='Found '+xs.length+' reference(s) · '+(r.source||'Public sources')+(r.note?' · '+r.note:'');
 $('#researchResults').innerHTML=xs.length?xs.map(x=>'<article class="researchcard"><a href="'+esc(x.url)+'" target="_blank" rel="noopener noreferrer">'+esc(x.title)+'</a><p>'+esc(x.snippet||'')+'</p></article>').join(''):'<div class="empty">No references found. Try a more specific question.</div>';
 return xs.length?'I found '+xs.length+' references using '+(r.source||'public sources')+'. The first results are '+xs.slice(0,3).map(x=>x.title).join('; ')+'. Open the research results for source links.':'I could not find references for that query.';
}
$('#researchForm').addEventListener('submit',async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const msg=await runResearch($('#researchQuery').value);toast(msg)}catch(err){$('#researchMeta').textContent=err.message;$('#researchResults').innerHTML='<div class="empty">Research could not be completed.</div>'}finally{b.disabled=false}});
async function voiceCommand(q){
 let s=q.replace(/^(hey|okay|ok)?\s*ultron[,:]?\s*/i,'').trim();
 if(!s||/^hello$|^are you there$/i.test(s))return "I'm here. What would you like me to do?";
 const researchMatch=s.match(/^(?:please )?(?:research|search the web for|look up|find information about)\s+(.+)/i);
 if(researchMatch)return await runResearch(researchMatch[1]);
 if(/^(stop listening|stop voice|turn off voice)$/i.test(s)){voiceLoop=false;$('#voiceConversation').textContent='Start voice conversation';$('#voiceConversation').setAttribute('aria-pressed','false');if(recognition){try{recognition.stop()}catch{}recognition=null}return 'Voice listening stopped.'}
 if(/^(prepare|plan) my day|^what('s| is) on my schedule/i.test(s)){const r=await req('/brief','POST',{});$('#briefText').textContent=r.brief.content;$('#briefMeta').textContent='Prepared just now · '+(r.calendar_connected===false?'Calendar not connected':'Calendar checked');return 'Your day plan is ready. '+r.brief.content.slice(0,650)}
 if(/^(read|show|list) my tasks|what are my tasks/i.test(s)){await loadItems();const open=items.filter(x=>['task','reminder'].includes(x.kind)&&x.status==='open');return open.length?'You have '+open.length+' open items: '+open.slice(0,8).map((x,i)=>(i+1)+'. '+x.title).join('; '):'You have no open tasks or reminders.'}
 const wantsReminder=/\bremind me\b|\breminder\b/i.test(s), wantsTask=/\b(add|create|make) (a )?(task|to-do)\b/i.test(s);
 if(wantsReminder||wantsTask){
   let title=s.replace(/^(please )?(remind me to|remind me|add (a )?task to|add (a )?task|create (a )?task to|create (a )?task|make (a )?task to)\s*/i,'').trim();
   let due=null;const now=new Date();let dayOffset=0;
   if(/\btomorrow\b/i.test(title)){dayOffset=1;title=title.replace(/\btomorrow\b/i,'')}
   else if(/\btoday\b/i.test(title)){title=title.replace(/\btoday\b/i,'')}
   const tm=title.match(/\bat (\d{1,2})(?::(\d{2}))?\s*(am|pm)?\b/i);
   if(tm){let h=Number(tm[1]),m=Number(tm[2]||0);if(tm[3]?.toLowerCase()==='pm'&&h<12)h+=12;if(tm[3]?.toLowerCase()==='am'&&h===12)h=0;if(!tm[3]&&h<=7)h+=12;if(h<24&&m<60){const d=new Date(now);d.setDate(d.getDate()+dayOffset);d.setHours(h,m,0,0);due=d.toISOString()}title=title.replace(tm[0],'')}
   title=title.replace(/[,.!?]+$/,'').trim();
   if(!title)return 'What should I add as the task or reminder?';
   const data=await req('/items','POST',{kind:wantsReminder?'reminder':'task',title,due_at:due});await loadItems();
   return (wantsReminder?'Reminder':'Task')+' saved: '+data.item.title+(due?' for '+new Date(due).toLocaleString():'')+'.';
 }
 const routine=s.match(/^(?:save|remember)(?: my)? routine\s*:?\s*(.+)/i);
 if(routine){await req('/memory','POST',{category:'routine',content:routine[1]});await loadMemories();return 'I saved that as one of your personal routines. I will include it in your daily plan.'}
 const mem=s.match(/^(remember that|remember this|save to memory)\s+(.+)/i);
 if(mem){await req('/memory','POST',{category:'voice note',content:mem[2]});await loadMemories();return 'I saved that to your private memory.'}
 return null;
}
async function researchForChat(q){const country=$('#newsCountry')?.value||'WORLD';const r=await req('/research?q='+encodeURIComponent(q)+'&country='+encodeURIComponent(country));const xs=(r.results||[]).filter(x=>x.title&&x.url).slice(0,8);const groups=r.comparisons||[];$('#researchQuery').value=q;$('#researchMeta').textContent='Live lookup · '+(r.source||'public sources')+' · '+groups.length+' coverage group(s)';$('#researchResults').innerHTML=groups.map(g=>'<article class="researchcard"><strong>'+esc(g.label)+'</strong><p>'+esc((g.publishers||[]).join(' · '))+' · '+(g.publisher_count||0)+' publisher(s)</p></article>').join('')+(xs.length?xs.map(x=>'<article class="researchcard"><a href="'+esc(x.url)+'" target="_blank" rel="noopener noreferrer">'+esc(x.title)+'</a><p>'+esc(x.snippet||x.description||'Open source for details.')+'</p><small>'+esc(x.source||'Publisher')+' · '+esc(x.published_at||'date not supplied')+'</small></article>').join(''):'<div class="empty">No usable public results.</div>');if(!xs.length)return 'I searched free public sources, but they returned no usable results. I will not guess about current events.';const status=groups.map(g=>g.label+': '+(g.publishers||[]).join(', ')).join('. ');return 'I checked current public sources just now. '+status+'. '+xs.map((x,i)=>(i+1)+'. '+x.title+'. '+String(x.snippet||x.description||'').slice(0,240)+' Publisher: '+(x.source||'unknown')+'. Published: '+(x.published_at||'date unavailable')+'. Source: '+x.url).join(' ')+' Publisher agreement is corroboration, not proof; disputed claims require inspecting the linked reports.';}
async function sendMessage(q,fromVoice=false){q=String(q||'').trim();if(!q)return;if(fromVoice)voiceBusy=true;$('#message').value='';bubble(q,'user');$('#chatStatus').textContent='ULTRON is preparing a reply…';let answer='';try{if(fromVoice){try{answer=await voiceCommand(q)||''}catch(e){answer='I heard you, but that action failed: '+(e.message||'unknown error')}}if(!answer&&!settings.ai_enabled&&/(election|war|conflict|invasion|ceasefire|breaking|latest|current events|news|president|prime minister|who won|results today|yesterday|what happened|what is happening|what's happening|happening in|latest on|update on|updates on|news about|Ukraine|Russia|Iran|Israel|Gaza|Sudan|Taiwan)/i.test(q)){try{answer=await researchForChat(q)}catch(e){answer='I tried to check free public sources, but live research is unavailable right now. I will not invent an answer. Open the Research panel and try again shortly.'}}if(!answer&&settings.ai_enabled){try{const r=await req('/chat','POST',{message:q,mode,conversation_id:conversationId,voice:fromVoice,deep:!!window.ultronDeep});answer=r.reply||'I could not produce a response.';loadActions();loadItems();loadMemories()}catch(e){answer='I could not reach the AI service: '+(e.message||'unknown error')+'. Your message was received.';if(e.code==='ai_setup_required'||e.status===412)answer+=' Connect an AI provider in Hatchable Setup.';if(e.code==='ai_spend_limit_reached')answer+=' No alternate paid provider was tried.'}}if(!answer)answer=localReply(q);if(!answer)answer='I heard you. Please tell me a little more.';lastReplyText=answer;bubble(answer,'bot');$('#chatStatus').textContent='Reply ready'+(settings.ai_enabled?' · AI brain enabled':' · basic mode; AI off');if(fromVoice||speakEnabled){$('#chatStatus').textContent='ULTRON is speaking…';speak(answer,()=>{voiceBusy=false;$('#chatStatus').textContent='Reply complete';if(voiceLoop)startRecognition(true)})}else{voiceBusy=false;if(voiceLoop)startRecognition(true)}}catch(e){const fallback='I heard you, but something went wrong while preparing my reply: '+(e.message||'unknown error');bubble(fallback,'bot');$('#chatStatus').textContent='Reply error';if(fromVoice)speak(fallback,()=>{voiceBusy=false;if(voiceLoop)startRecognition(true)});else voiceBusy=false}}
let visionStream=null,visionFrame=null;
function stopVisionCamera(){
 if(visionStream){visionStream.getTracks().forEach(t=>t.stop());visionStream=null}
 const v=$('#visionVideo');if(v){v.pause();v.srcObject=null;v.hidden=true}
 $('#visionStart').disabled=false;$('#visionCapture').disabled=true;$('#visionAnalyze').disabled=true;$('#visionStop').disabled=true;
 $('#visionState').textContent='CAMERA OFF';
 $('#visionStatus').textContent='Camera stopped. No live video is being accessed.';
}
$('#visionStart').addEventListener('click',async()=>{
 if(!navigator.mediaDevices?.getUserMedia){$('#visionStatus').textContent='Camera access is unavailable in this browser. Open ULTRON in Safari over HTTPS and check camera permissions.';return}
 if(!confirm('Allow ULTRON to use your camera for this session? The live preview stays on this device. No image will be uploaded or recorded.'))return;
 try{
  visionStream=await navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}}});
  const v=$('#visionVideo');v.srcObject=visionStream;v.hidden=false;await v.play();
  $('#visionStart').disabled=true;$('#visionCapture').disabled=false;$('#visionStop').disabled=false;
  $('#visionState').textContent='CAMERA ACTIVE';$('#visionStatus').textContent='Camera active on this device only. Tap Capture a frame or Stop camera.';
 }catch(e){stopVisionCamera();$('#visionStatus').textContent='Camera was not opened: '+(e.name==='NotAllowedError'?'permission denied':e.name==='NotFoundError'?'no camera found':String(e.message||e));}
});
$('#visionCapture').addEventListener('click',()=>{
 const v=$('#visionVideo'),c=$('#visionCanvas');if(!visionStream||!v.videoWidth)return;
 c.width=v.videoWidth;c.height=v.videoHeight;c.getContext('2d').drawImage(v,0,0,c.width,c.height);
 visionFrame=c.toDataURL('image/jpeg',0.82);$('#visionAnalyze').disabled=false;
 const preview=$('#visionPreview');preview.innerHTML='';const img=document.createElement('img');img.alt='Camera frame captured locally';img.src=visionFrame;preview.append(img);preview.hidden=false;
 $('#visionStatus').textContent='Frame captured locally. It has not been sent, stored, or analysed. Stop the camera when finished.';
});
$('#visionAnalyze').addEventListener('click',async()=>{if(!visionFrame)return;const ok=confirm('Send this single captured image to NVIDIA Llama 3.2 Vision now? NVIDIA trial terms may allow submitted images and outputs to be recorded to improve its services. Do not send private, confidential or sensitive surroundings. No image will be sent unless you approve this prompt.');if(!ok)return;$('#visionAnalyze').disabled=true;$('#visionStatus').textContent='Sending this one approved frame to NVIDIA for analysis…';try{const result=await req('/vision','POST',{image:visionFrame,consent:true});const answer=result.reply||'No description returned.';bubble('VISUAL AWARENESS · NVIDIA\n'+answer,'bot');$('#visionStatus').textContent='Analysis complete via '+(result.provider||'NVIDIA')+'. This was a one-time image submission; camera stream remains local.';}catch(error){$('#visionStatus').textContent='Vision analysis failed: '+(error.message||'unknown error')+'. No automatic paid fallback was attempted.';}finally{$('#visionAnalyze').disabled=false;}});$('#visionStop').addEventListener('click',stopVisionCamera);
document.addEventListener('visibilitychange',()=>{if(document.hidden&&visionStream)stopVisionCamera()});
window.addEventListener('pagehide',stopVisionCamera);

$('#chatForm').addEventListener('submit',e=>{e.preventDefault();sendMessage($('#message').value)});
$('#modes').addEventListener('click',e=>{const b=e.target.closest('[data-mode]');if(!b)return;mode=b.dataset.mode;document.querySelectorAll('.mode').forEach(x=>x.classList.toggle('active',x===b));bubble('Mode set to '+mode+'. What would you like help with?','bot')});
function startRecognition(handsFree=false){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){toast('This browser does not expose live speech recognition. Use the microphone on your iPhone keyboard to dictate, or try a supported browser.');voiceLoop=false;$('#voiceConversation').textContent='Start voice conversation';return}if(voiceRestartTimer){clearTimeout(voiceRestartTimer);voiceRestartTimer=null}if(recognition){try{recognition.stop()}catch{}recognition=null}const instance=new SR();recognition=instance;instance.lang='en-US';instance.interimResults=true;instance.continuous=false;instance.maxAlternatives=1;let finalText='',interimText='',heardAny=false,submitted=false;const submitHeard=heard=>{if(submitted||!heard.trim())return;submitted=true;const text=heard.trim();if(wakeWordMode&&handsFree){const lower=text.toLowerCase();const at=lower.indexOf('ultron');const prefix=at>=0?lower.slice(Math.max(0,at-8),at):'';if(at>=0&&(prefix.includes('hey')||prefix.includes('okay')||prefix.includes('ok'))){const command=text.slice(at+6).trim().replace(/^[,: .-]+/,'')||'I am here. What would you like me to do?';$('#message').value=command;voiceBusy=true;sendMessage(command,true)}else{$('#chatStatus').textContent='Wake phrase mode is on · say Hey ULTRON'}}else{$('#message').value=text;if(handsFree){voiceBusy=true;sendMessage(text,true)}}};instance.onresult=e=>{let interim='';for(let i=e.resultIndex;i<e.results.length;i++){const transcript=e.results[i][0].transcript;if(transcript.trim())heardAny=true;if(e.results[i].isFinal)finalText+=transcript;else interim+=transcript}if(interim.trim()){interimText=interim;if(!wakeWordMode)$('#message').value=interim}if(finalText.trim())submitHeard(finalText)};instance.onerror=e=>{const reason=e.error||'unknown error';$('#chatStatus').textContent='Microphone error: '+reason+'. Check Safari microphone permission and speech recognition support.';toast(reason==='not-allowed'||reason==='service-not-allowed'?'Microphone permission is blocked. Allow it for this site in iPhone Settings > Safari > Microphone.':'Voice input failed: '+reason);voiceBusy=false;if(voiceLoop){voiceLoop=false;$('#voiceConversation').textContent='Start voice conversation';$('#voiceConversation').setAttribute('aria-pressed','false')}if(recognition===instance){try{instance.stop()}catch{}recognition=null}};instance.onaudiostart=()=>{$('#chatStatus').textContent='Microphone audio stream opened · speak now'};instance.onspeechstart=()=>{$('#chatStatus').textContent='Speech detected · listening'};instance.onspeechend=()=>{$('#chatStatus').textContent='Speech ended · processing words'};instance.onstart=()=>{$('#chatStatus').textContent='Listening now · English (US) · speak your request';$('#ultronTalk').classList.add('listening')};instance.onend=()=>{$('#ultronTalk').classList.remove('listening');if(recognition===instance)recognition=null;if(!submitted&&(finalText.trim()||interimText.trim()))submitHeard(finalText.trim()||interimText.trim());if(!heardAny&&!submitted&&!voiceLoop&&handsFree&&!voiceBusy){$('#chatStatus').textContent='No speech reached the browser. Tap ULTRON and try again.';toast('No speech reached the browser. Check microphone permission and try speaking after Listening appears.')}if(voiceLoop&&handsFree&&!voiceBusy){if(voiceRestartTimer)clearTimeout(voiceRestartTimer);voiceRestartTimer=setTimeout(()=>{voiceRestartTimer=null;if(voiceLoop&&!voiceBusy)startRecognition(true)},650)}};try{instance.start();$('#chatStatus').textContent=handsFree?'Voice conversation · listening':'Microphone ready · speak now'}catch(e){if(recognition===instance)recognition=null;toast('Could not start the microphone. Check browser permission and try again.');if(handsFree){voiceLoop=false;$('#voiceConversation').textContent='Start voice conversation'}}}
$('#mic').addEventListener('click',()=>startRecognition(false));
$('#ultronTalk').addEventListener('click',e=>{e.preventDefault();e.stopPropagation();if(recognition){try{recognition.stop()}catch{}recognition=null;$('#ultronTalk').classList.remove('listening');$('#chatStatus').textContent='Listening stopped.';toast('Listening stopped.');return}if('speechSynthesis'in window)window.speechSynthesis.cancel();$('#chatStatus').textContent='ULTRON is opening the microphone…';toast('ULTRON activated. Starting microphone…');startRecognition(true)});
$('#voiceConversation').addEventListener('click',()=>{voiceLoop=!voiceLoop;$('#voiceConversation').textContent=voiceLoop?'Stop voice conversation':'Start voice conversation';$('#voiceConversation').setAttribute('aria-pressed',String(voiceLoop));$('#voiceConversation').classList.toggle('voice-active',voiceLoop);if(voiceLoop){wakeWordMode=false;$('#wakeWordToggle').textContent='Enable Hey ULTRON';$('#wakeWordToggle').setAttribute('aria-pressed','false');voiceBusy=false;toast('Voice mode is on. Speak naturally; ULTRON will reply aloud.');startRecognition(true)}else{voiceBusy=false;if(voiceRestartTimer){clearTimeout(voiceRestartTimer);voiceRestartTimer=null}if(recognition){try{recognition.stop()}catch{}recognition=null}if('speechSynthesis'in window)window.speechSynthesis.cancel();$('#chatStatus').textContent=settings.ai_enabled?'AI brain enabled':'Basic guidance · AI off';toast('Voice conversation stopped.')}});
$('#wakeWordToggle').addEventListener('click',()=>{const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!wakeWordMode&&!SR){toast('Live wake phrase listening is not supported in this browser.');return}wakeWordMode=!wakeWordMode;voiceLoop=wakeWordMode;if(wakeWordMode){voiceBusy=false;$('#wakeWordToggle').textContent='Disable Hey ULTRON';$('#wakeWordToggle').setAttribute('aria-pressed','true');$('#voiceConversation').textContent='Stop voice conversation';$('#voiceConversation').setAttribute('aria-pressed','true');$('#wakeWordNote').textContent='Listening for Hey ULTRON. Keep this page open and active. Background and locked-screen listening are not available.';startRecognition(true)}else{voiceBusy=false;$('#wakeWordToggle').textContent='Enable Hey ULTRON';$('#wakeWordToggle').setAttribute('aria-pressed','false');$('#voiceConversation').textContent='Start voice conversation';$('#voiceConversation').setAttribute('aria-pressed','false');if(voiceRestartTimer){clearTimeout(voiceRestartTimer);voiceRestartTimer=null}if(recognition){try{recognition.stop()}catch{}recognition=null}if('speechSynthesis'in window)window.speechSynthesis.cancel();$('#chatStatus').textContent='Wake phrase listening is off.';$('#wakeWordNote').textContent='Wake phrase mode is off. It only works while this page is open and active.'}});$('#voiceToggle').addEventListener('click',()=>{speakEnabled=!speakEnabled;$('#voiceToggle').textContent=speakEnabled?'◖))':'◖×';$('#voiceToggle').title=speakEnabled?'Voice replies on':'Voice replies off';toast(speakEnabled?'Voice replies on':'Voice replies off')});
async function loadSettings(){try{const r=await req('/settings');settings={...settings,...r.settings};const deviceZone=Intl.DateTimeFormat().resolvedOptions().timeZone;if(deviceZone&&settings.timezone!==deviceZone){try{const z=await req('/settings','PUT',{timezone:deviceZone});settings={...settings,...z.settings}}catch(e){console.warn('Could not sync device timezone',e.message)}}$('#aiState').textContent=settings.ai_enabled?'AI ON':'AI OFF';$('#heroAiState').textContent=settings.ai_enabled?'ACTIVE':'STANDBY';$('#heroAiMode').textContent=settings.ai_enabled?'CONNECTED AI':'FREE MODE';$('#aiToggle').textContent=settings.ai_enabled?'Disable AI':'Enable AI';$('#chatStatus').textContent=settings.ai_enabled?'AI brain enabled':'Basic guidance mode';$('#memoryToggle').checked=settings.memory_enabled;$('#dailyToggle').checked=settings.daily_brief_enabled;$('#aiBriefToggle').checked=settings.daily_ai_brief;$('#briefHour').value=String(settings.daily_brief_hour);if(!settings.memory_enabled)$('#memoriesList').innerHTML='<div class="empty">Long-term memory is paused.</div>';}catch(e){toast(e.message)}}
$('#aiToggle').addEventListener('click',async()=>{const enable=!settings.ai_enabled;if(enable&&!window.__aiArmed){window.__aiArmed=true;$('#aiToggle').textContent='Tap again to confirm';toast('Tap again to confirm. ULTRON only uses your connected AI keys when you send a message.');setTimeout(()=>{window.__aiArmed=false;if(!settings.ai_enabled)$('#aiToggle').textContent='Enable AI'},6000);return}window.__aiArmed=false;try{const r=await req('/settings','PUT',{ai_enabled:enable});settings={...settings,...r.settings};$('#aiState').textContent=settings.ai_enabled?'AI ON':'AI OFF';$('#aiToggle').textContent=settings.ai_enabled?'Disable AI':'Enable AI';$('#chatStatus').textContent=settings.ai_enabled?'AI brain enabled':'Basic guidance mode';toast(enable?'AI enabled. Connect a provider in Hatchable Setup if you have not already.':'AI switched off.')}catch(e){toast(e.message)}});
$('#saveSettings').addEventListener('click',async()=>{try{const r=await req('/settings','PUT',{memory_enabled:$('#memoryToggle').checked,daily_brief_enabled:$('#dailyToggle').checked,daily_ai_brief:$('#aiBriefToggle').checked,daily_brief_hour:Number($('#briefHour').value),timezone:Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC'});settings={...settings,...r.settings};toast('ULTRON controls saved.');loadSettings()}catch(e){toast(e.message)}});
