function missionGraphHtml(steps,live=false){const xs=Array.isArray(steps)?steps:[];if(!xs.length)return '<p class="tiny">No task graph is available.</p>';const role=t=>({research_search:'RESEARCHER',retrieve_source:'RESEARCHER',verify_url:'RESEARCHER',assess_claim:'ANALYST',save_learning:'EXECUTOR',create_task:'EXECUTOR',skill_apply:'EXECUTOR'}[t]||'COORDINATOR');return '<div class="mission-graph">'+xs.map((s,i)=>{const deps=Array.isArray(s.depends_on)?s.depends_on:[],state=String(s.status||'planned').toUpperCase();return '<article class="mission-node"><div class="mission-node-top"><span>STEP '+(s.position||i+1)+'</span><span>'+esc(live?state:'PLANNED')+'</span></div><b>'+esc(s.title||s.step_type||s.type||'Mission step')+'</b><small>'+esc(role(s.step_type||s.type))+' · '+esc(s.step_type||s.type||'operation')+'</small><p>'+(deps.length?'WAITING FOR '+deps.map(n=>'#'+esc(n)).join(', '):'INDEPENDENT · READY TO RUN')+'</p></article>'}).join('')+'</div><p class="tiny">Dependency links are shown on each step. Independent steps can run in parallel (maximum 3); dependent steps wait for successful prerequisites.</p>'}
