$('#agentForm').addEventListener('submit',async e=>{
 e.preventDefault();const b=e.submitter;b.disabled=true;b.textContent='Queuing mission…';
 try{
  const title=$('#agentTitle').value.trim(),objective=$('#agentObjective').value.trim(),query=$('#agentQuery').value.trim(),verifyUrl=$('#agentVerifyUrl').value.trim(),topic=$('#agentLearnTopic').value.trim(),summary=$('#agentLearnSummary').value.trim(),taskTitle=$('#agentTaskTitle').value.trim(),skillId=$('#agentSkill').value,skillTask=$('#agentSkillTask').value.trim(),skillMetric=$('#agentSkillMetric').value.trim(),skillDirection=$('#agentSkillDirection').value,skillBaseline=$('#agentSkillBaseline').value,skillBaselineEvidence=$('#agentSkillBaselineEvidence').value.trim();
  if(Boolean(topic)!==Boolean(summary))throw new Error('Enter both a learning topic and its summary, or leave both blank.');
  if(skillId&&(!skillTask||!skillMetric||skillBaseline===''||skillBaselineEvidence.length<12))throw new Error('A mastered skill application needs a practical task, metric label, numeric baseline and a note explaining how the baseline was measured.');
  const steps=draftedAgentPlan?draftedAgentPlan.map(s=>({...s})): [];
  if(skillId)steps.push({type:'skill_apply',title:'Apply mastered skill in practical work',input:{skill_id:skillId,task_description:skillTask,metric_label:skillMetric,metric_direction:skillDirection,baseline_value:Number(skillBaseline),baseline_evidence:skillBaselineEvidence}});
  if(!draftedAgentPlan){
   if(!query)throw new Error('Enter a research question or draft a plan from your objective.');
   steps.push({type:'research_search',title:'Research the objective',input:{query}});
   if(verifyUrl)steps.push({type:'verify_url',title:'Verify the supplied source',input:{url:verifyUrl}});
   if(topic&&summary)steps.push({type:'save_learning',title:'Save verified learning',input:{topic,summary,source_url:verifyUrl}});
   if(taskTitle)steps.push({type:'create_task',title:'Apply the mission as a follow-up task',input:{title:taskTitle,body:objective}});
  }
  if(steps.length>8)throw new Error('This mission has too many steps.');
  const r=await req('/agent','POST',{title,objective,steps,acceptanceCriteria:draftedAgentAcceptance,acceptanceChecks:draftedAgentAcceptanceChecks});
  e.target.reset();draftedAgentPlan=null;draftedAgentAcceptance=[];draftedAgentAcceptanceChecks=[];$('#agentPlanPreviewResult').textContent='Mission launched. Draft another plan when ready.';await loadAgentRuns();await inspectAgentRun(r.runId);toast(r.workerQueued?'Mission saved and background execution queued.':'Mission saved; recovery worker will pick it up.');
 }catch(err){toast(err.message)}finally{b.disabled=false;b.textContent='Launch mission ↗'}
});
